class WindowConfig {
    private int width = 800;
    private int height = 600;
    public WindowConfig setWidth(int w) { this.width = w; return this; }
    public WindowConfig setHeight(int h) { this.height = h; return this; }
    public int getArea() { return width * height; }
}
public class WindowApp {
    public static void main(String[] args) {
        WindowConfig cfg = new WindowConfig().setWidth(100).setHeight(50);
        System.out.println(cfg.getArea());
    }
}
